import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Decreasing stack: its top is the nearest strictly greater element to the left.
        int[] stack = new int[n];
        int size = 0;
        long answer = 0;
        for (int i = 0; i < n; i++) {
            while (size > 0 && a[stack[size - 1]] <= a[i]) size--;
            if (size > 0) answer += stack[size - 1] + 1;
            stack[size++] = i;
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Decreasing stack: its top is the nearest strictly greater element to the left.
	stack := make([]int, 0, n)
	answer := 0
	for i, v := range a {
		for len(stack) > 0 && a[stack[len(stack)-1]] <= v {
			stack = stack[:len(stack)-1]
		}
		if len(stack) > 0 {
			answer += stack[len(stack)-1] + 1
		}
		stack = append(stack, i)
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
